function TIE_CORRECTION(L):
    return (sum over m in L of (m^3 - m)) / 12          # exact rational

function ATTAINABLE_CEILING(L):
    n <- sum of L
    require n >= 2
    return 1 - (sum over m in L of (m^3 - m)) / (n^3 - n)

function VALUATION_PROFILE(p, b):
    L <- empty list
    for k from b-1 down to 0:
        append (p-1) * p^k to L        # residues with exactly b-1-k trailing zeros
    append 1 to L                       # the residue 0, a class of its own
    return L

function CEILING_LAW(p, b):
    Y <- p^b
    return 3p/(p^2 + p + 1) * (1 + 1/(Y*(Y+1)))

function VERIFY(p, b):
    return ATTAINABLE_CEILING(VALUATION_PROFILE(p, b)) == CEILING_LAW(p, b)

