function PI_CEILING(x):
    return 3x / (x^2 + x + 1)

function EFFECTIVE_BASE(r):                # 0 < r < 1
    D <- 3 * (1 - r) * (3 + r)             # discriminant, nonnegative
    return ((3 - r) + sqrt(D)) / (2r)      # larger root of r x^2 -(3-r)x + r

function CONJUGATE_BASE(r):
    return ((3 - r) - sqrt(3(1-r)(3+r))) / (2r)     # equals 1 / EFFECTIVE_BASE(r)

function INTEGER_BASES_IN_WINDOW(lo, hi):
    out <- empty list
    for p from 2 upward:
        v <- PI_CEILING(p)
        if v < lo: break                   # pi is strictly decreasing
        if v <= hi: append p to out
    return out

function INVERT_DIAL(rho, window):
    r <- rho^2
    beta <- EFFECTIVE_BASE(r)
    nearest <- max(2, round(beta))
    report beta, 1/beta, nearest, |PI_CEILING(nearest) - r|,
           |PI_CEILING(beta) - r|, INTEGER_BASES_IN_WINDOW(window)

function RHO_RANK(R, S):
    n <- length of R
    return 1 - 6 * (sum over i of (R_i - S_i)^2) / (n^3 - n)

function LIPSCHITZ_BOUND(n, a):            # a = |A|
    return 6 * a * (n-1)^2 / (n^3 - n)     # <= 6a/n

function MINIMUM_CORRUPTION(n, delta):
    return ceil(delta * n / 6)             # lower bound, contrapositive

function EXTREMAL_SWAP_INCREMENT(n):
    return 12 * (n - 1) / (n * (n + 1))    # exact one-transposition move

function REALISE_MOVE(n, delta):
    R <- (1, 2, ..., n); S <- copy of R; k <- 0
    while RHO_RANK(R,R) - RHO_RANK(R,S) < delta and 2(k+1) <= n:
        swap S[k] and S[n-1-k]             # disjoint extreme transposition
        k <- k + 1
    return 2k re-ranked observations, attained RHO_RANK(R,S)
